// =====================================================================
//  図形 2687〜(Q6Art の種類 65〜):「部品の並び」で描く絵の図形(アイコン)
//   絵は IconB の部品(楕円・四角・太い線・多角形・輪)の並びで書き、2D はそのまま塗り、専用3Dモデルは部品に厚みを付けて重ねる
//   色: M=メインの色(Color1)、S=サブの色(Color2)、それ以外は決まった色
//   65=動物の顔 66=果物 67=野菜 68=乗り物 69=建物 70=道具 71=楽器 72=服・小物 73=食べ物 74=飲み物
//   85=和のおもちゃ 86=おもちゃ 87=屋台 88=キャンプ 89=お店 90=病院 91=台所 92=道路 93=絵と工作 94=パン 95=家の小物 96=学校
//   75=虫 76=海の生き物 77=鳥 78=家電 79=デバイス 80=家具 81=手のサイン 82=植物 83=宇宙 84=スポーツ用品
// =====================================================================
public abstract partial class Q6Art
{
    internal const uint IM = 0x1000001, IS = 0x1000002, IK = 0x2A2E35, IW = 0xFFFFFF;

    /// <summary>アイコンの部品。T: e=楕円(A,B 半径C,D) r=四角(中心A,B 幅C 高さD 角E) l=太い線(A,B→C,D 太さE) p=多角形 o=輪(A,B 半径C 太さD)</summary>
    internal readonly record struct IconOp(char T, float A, float B, float C, float D, float E, uint Col, float[]? P = null);

    internal sealed class IconB
    {
        public readonly List<IconOp> Ops = new();
        public void C(float x, float y, float r, uint col) => Ops.Add(new('e', x, y, r, r, 0, col));
        public void E(float x, float y, float rx, float ry, uint col) => Ops.Add(new('e', x, y, rx, ry, 0, col));
        public void R(float x, float y, float w, float h, float rad, uint col) => Ops.Add(new('r', x, y, w, h, rad, col));
        public void L(float x0, float y0, float x1, float y1, float w, uint col) => Ops.Add(new('l', x0, y0, x1, y1, w, col));
        public void P(uint col, params float[] xy) => Ops.Add(new('p', 0, 0, 0, 0, 0, col, xy));
        public void O(float x, float y, float r, float w, uint col) => Ops.Add(new('o', x, y, r, w, 0, col));
        public void Arc(float x, float y, float r, float a0, float a1, float w, uint col)
        {
            int n = Math.Max(3, (int)(MathF.Abs(a1 - a0) * r / 28f));
            for (int i = 0; i < n; i++) { float b0 = a0 + (a1 - a0) * i / n, b1 = a0 + (a1 - a0) * (i + 1) / n; L(x + MathF.Cos(b0) * r, y + MathF.Sin(b0) * r, x + MathF.Cos(b1) * r, y + MathF.Sin(b1) * r, w, col); }
        }
        /// <summary>扇形・半円(中心から a0〜a1 の弧)</summary>
        public void Pie(float x, float y, float rx, float ry, float a0, float a1, uint col)
        {
            var l = new List<float> { x, y }; int n = 18;
            for (int k = 0; k <= n; k++) { float a = a0 + (a1 - a0) * k / n; l.Add(x + MathF.Cos(a) * rx); l.Add(y + MathF.Sin(a) * ry); }
            P(col, l.ToArray());
        }
        public void Eyes(float y, float gap, float r, float x = 0) { C(x - gap, y, r, IK); C(x + gap, y, r, IK); C(x - gap + r * .3f, y - r * .35f, r * .32f, IW); C(x + gap + r * .3f, y - r * .35f, r * .32f, IW); }
        public void Star(float x, float y, float r, uint col) { var l = new float[20]; for (int k = 0; k < 10; k++) { float a = -MathF.PI / 2f + k * MathF.PI / 5f, q = k % 2 == 0 ? r : r * .45f; l[k * 2] = x + MathF.Cos(a) * q; l[k * 2 + 1] = y + MathF.Sin(a) * q; } P(col, l); }
        public void Leaf(float x, float y, float len, float wid, float ang, uint col)
        {
            var l = new List<float>(); float c = MathF.Cos(ang), s = MathF.Sin(ang);
            for (int k = 0; k <= 16; k++) { float t = k / 16f, u = (t - .5f) * len, v = MathF.Sin(t * MathF.PI) * wid; l.Add(x + c * u - s * v); l.Add(y + s * u + c * v); }
            for (int k = 15; k >= 1; k--) { float t = k / 16f, u = (t - .5f) * len, v = -MathF.Sin(t * MathF.PI) * wid; l.Add(x + c * u - s * v); l.Add(y + s * u + c * v); }
            P(col, l.ToArray());
        }
        public void Wheel(float x, float y, float r) { C(x, y, r, IK); C(x, y, r * .45f, 0xB8C0CC); }
        public void Tri(float x, float y, float w, float h, uint col) => P(col, x, y - h / 2f, x + w / 2f, y + h / 2f, x - w / 2f, y + h / 2f);
    }

