    internal static (string Name, uint M, uint S, Action<IconB> Draw) IconItem(int kind, int a)
    {
        var arr = Icons.TryGetValue(kind, out var a0) ? a0 : MoreIcons[kind];
        return arr[Math.Clamp(a, 0, arr.Length - 1)];
    }
    internal static List<IconOp> IconOps(int kind, int a) { var b = new IconB(); IconItem(kind, a).Draw(b); return b.Ops; }

    void Icon2D(ArtPen p, float t, Color4 C, Color4 D)
    {
        float bob = MathF.Sin(t * 2f) * 8f, rot = MathF.Sin(t * 1.3f) * .03f;
        Color4 Col(uint c) => c == IM ? C : c == IS ? D : p.C(c);
        p.Move(0, bob, () => p.Turn(0, 0, rot, () =>
        {
            foreach (var o in IconOps(kind, a))
            {
                var col = Col(o.Col);
                switch (o.T)
                {
                    case 'e': p.E(o.A, o.B, o.C, o.D, col); break;
                    case 'r': p.R(o.A, o.B, o.C, o.D, o.E, col); break;
                    case 'l': p.L(o.A, o.B, o.C, o.D, col, o.E); p.D(o.A, o.B, o.E / 2f, col); p.D(o.C, o.D, o.E / 2f, col); break;
                    case 'p': if (o.P is { Length: >= 6 } xy) p.F(col, xy); break;
                    case 'o': p.Ring(o.A, o.B, o.C, col, o.D); break;
                }
            }
        }));
    }
}
